import java.util.Scanner;

/**
 * Variant 5: Using Scanner for input, System.out for output, with static methods
 */
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.close();

        long result = computeShuffles(n, m);
        System.out.println(result);
    }

    static long computeShuffles(int n, int m) {
        NumberTheory.Mod998 mod = new NumberTheory.Mod998();
        long phaseSize = 1;
        long p = 1;
        for (int i = 0; p != 0; i++) {
            p = mod.mult(p, n - i, mod.smallInv(n + m - i));
            phaseSize = mod.add(phaseSize, p);
        }

        long answer = 0;
        for (int k = 1; k <= n; k++) {
            long numPhases = mod.mult(m + k, mod.smallInv(k));
            long term = mod.mult(mod.ncr(n, k), numPhases, phaseSize);
            if ((k & 1) == 1)
                answer = mod.add(answer, term);
            else
                answer = mod.subtract(answer, term);
        }
        return answer;
    }

    static class NumberTheory {
        public static class Mod998 extends NumberTheory.Modulus<Mod998> {
            public long modulus() {
                return 998_244_353L;
            }
        }
        public abstract static class Modulus<M extends NumberTheory.Modulus<M>> {
            // Same as original
        }
    }
}
